css:
.print-format { padding: 0 !important; margin: 0 !important; }
.mi4 { width: 96mm; font-family: "DejaVu Sans Mono", "Courier New", monospace; font-size: 11px; line-height: 1.3; color: #000; }
.mi4 table { width: 100%; border-collapse: collapse; }
.mi4 td { padding: 0 1px; vertical-align: top; }
.mi4 .kv td:first-child { width: 38%; }
.mi4 .c { text-align: center; }
.mi4 .r { text-align: right; white-space: nowrap; }
.mi4 .b { font-weight: bold; }
.mi4 .big { font-size: 13px; }
.mi4 .rule { border-top: 1px dashed #000; margin: 4px 0; }

.mi4 .small td { font-size: 0.85em; }

html:
{%- set agent_name = frappe.db.get_value("Mobile Trip", doc.mobile_trip, "agent_name") if doc.mobile_trip else "" -%}
{%- set payable = doc.grand_total if (doc.disable_rounded_total or not doc.rounded_total) else doc.rounded_total -%}
{#- Return credit set off by Credit Note journal entries (mobile set-off): on an invoice the credit it received, on a credit note where its credit went. -#}
{%- set jea = frappe.get_all("Journal Entry Account", filters={"reference_type": "Sales Invoice", "reference_name": doc.name, "docstatus": 1}, fields=["parent", "debit", "credit"]) -%}
{%- set cn_jes = frappe.get_all("Journal Entry", filters={"name": ["in", (jea | map(attribute="parent") | list) or [""]], "voucher_type": "Credit Note", "docstatus": 1}, pluck="name") -%}
{%- set ns_cr = namespace(applied=0, targets=[]) -%}
{%- for r in jea %}{% if r.parent in cn_jes %}{% set ns_cr.applied = ns_cr.applied + (r.debit if doc.is_return else r.credit) %}{% endif %}{% endfor -%}
{%- if doc.is_return and cn_jes %}{% set ns_cr.targets = frappe.get_all("Journal Entry Account", filters={"parent": ["in", cn_jes], "reference_type": "Sales Invoice", "reference_name": ["!=", doc.name], "credit": [">", 0]}, fields=["reference_name", "credit"], order_by="idx") %}{% endif -%}
{%- set credit_applied = ns_cr.applied -%}
{%- set paid = payable - doc.outstanding_amount - (0 if doc.is_return else credit_applied) -%}
{%- set cur = {"fieldtype": "Currency", "options": doc.currency} -%}
{%- set ns = namespace(line_discount=false) -%}
{%- for item in doc.items %}{% if item.price_list_rate and (item.price_list_rate - item.rate) > 0.004 %}{% set ns.line_discount = true %}{% endif %}{% endfor -%}
{%- set previous = frappe.get_all("Sales Invoice", filters={"customer": doc.customer, "company": doc.company, "docstatus": 1, "outstanding_amount": [">", 0], "name": ["!=", doc.name]}, pluck="outstanding_amount") | sum -%}
<div class="mi4">
	<div class="c b big">{{ doc.company }}</div>
	{%- if doc.company_tax_id %}<div class="c">{{ _("Tax ID") }}: {{ doc.company_tax_id }}</div>{% endif %}
	<div class="c b">{{ _("INVOICE") if not doc.is_return else _("CREDIT NOTE") }}</div>
	<div class="rule"></div>
	<table class="kv">
		<tr><td>{{ _("No") }}</td><td>{{ doc.name }}</td></tr>
		<tr><td>{{ _("Date") }}</td><td>{{ frappe.format(doc.posting_date, "Date") }} {{ (doc.posting_time | string)[:5] }}</td></tr>
		<tr><td>{{ _("Customer") }}</td><td>{{ doc.customer_name }}</td></tr>
		{%- if agent_name %}<tr><td>{{ _("Agent") }}</td><td>{{ agent_name }}</td></tr>{% endif %}
	</table>
	<div class="rule"></div>
	<table class="items">
		<tr class="b"><td>{{ _("Item") }}</td><td class="r">{{ _("Qty") }}</td><td class="r">{{ _("Rate") }}</td><td class="r">{{ _("Amount") }}</td></tr>
		{%- for item in doc.items %}
		<tr><td colspan="4">{{ item.item_name }}</td></tr>
		{%- set off = item.price_list_rate - item.rate if item.price_list_rate else 0 %}
		{%- if off > 0.004 %}
		<tr class="small"><td colspan="4">{{ _("List") }} {{ item.get_formatted("price_list_rate", doc) }} − {{ _("Disc.") }} {{ "%.2f" | format(off / item.price_list_rate * 100) }}% ({{ frappe.format(off, cur) }} / {{ item.uom }})</td></tr>
		{%- endif %}
		<tr><td></td><td class="r">{{ item.get_formatted("qty") }} {{ item.uom }}</td><td class="r">{{ item.get_formatted("rate", doc) }}</td><td class="r">{{ item.get_formatted("amount", doc) }}</td></tr>
		{%- endfor %}
	</table>
	<div class="rule"></div>
	<table class="kv totals">
		{%- if doc.discount_amount or ns.line_discount %}
		<tr><td>{{ _("Subtotal") }}</td><td class="r">{{ doc.get_formatted("total") }}</td></tr>
		{%- endif %}
		{%- if doc.discount_amount %}
		<tr><td>{{ _("Invoice discount") }}{% if doc.additional_discount_percentage %} ({{ "%g" | format(doc.additional_discount_percentage) }}%){% endif %}</td><td class="r">-{{ frappe.format(doc.discount_amount | abs, cur) }}</td></tr>
		{%- endif %}
		<tr><td>{{ _("Net Total") }}</td><td class="r">{{ doc.get_formatted("net_total") }}</td></tr>
		{%- for tax in doc.taxes %}{% if tax.tax_amount %}
		<tr><td>{{ tax.description }}</td><td class="r">{{ tax.get_formatted("tax_amount", doc) }}</td></tr>
		{%- endif %}{% endfor %}
		{%- if doc.rounding_adjustment and payable != doc.grand_total %}
		<tr><td>{{ _("Grand Total") }}</td><td class="r">{{ doc.get_formatted("grand_total") }}</td></tr>
		<tr><td>{{ _("Rounding adjustment") }}</td><td class="r">{{ doc.get_formatted("rounding_adjustment") }}</td></tr>
		{%- endif %}
		<tr class="b"><td>{{ _("Total") }}</td><td class="r">{{ frappe.format(payable, cur) }}</td></tr>
		{%- if doc.is_return %}
		{%- for t in ns_cr.targets %}
		<tr><td>{{ _("Credit applied to") }} {{ t.reference_name }}</td><td class="r">{{ frappe.format(t.credit, cur) }}</td></tr>
		{%- endfor %}
		<tr><td>{{ _("Credit left on account") }}</td><td class="r">{{ frappe.format(-doc.outstanding_amount if doc.outstanding_amount < 0 else 0, cur) }}</td></tr>
		{%- else %}
		{%- if credit_applied %}
		<tr><td>{{ _("Return credit applied") }}</td><td class="r">-{{ frappe.format(credit_applied, cur) }}</td></tr>
		{%- endif %}
		<tr><td>{{ _("Paid (cash)") }}</td><td class="r">{{ frappe.format(paid, cur) }}</td></tr>
		<tr><td>{{ _("Balance") }}</td><td class="r">{{ doc.get_formatted("outstanding_amount") }}</td></tr>
		{%- endif %}
		<tr><td>{{ _("Previous Outstanding") }}</td><td class="r">{{ frappe.format(previous, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>
		<tr class="b"><td>{{ _("Total Due") }}</td><td class="r">{{ frappe.format(previous + doc.outstanding_amount, {"fieldtype": "Currency", "options": doc.currency}) }}</td></tr>
	</table>
	<div class="rule"></div>
	<div class="c">{{ _("Thank you for your business") }}</div>
</div>
